// Sous-catégories DDM du catalogue existant
const SERRURES = 'Serrures connectées'
const INTERPHONES = 'Interphones & visiophones'
const VIDEO = 'Vidéosurveillance'
const DOMOTIQUE = 'Maison connectée'
const QUINC = 'Quincaillerie'
const BRICO = 'Bricolage & outillage'
const DOMOTIQUE_CAT = 'Maison connectée'
const SECU = 'Sécurité & surveillance' as const

interface LockOpts {
  cat?: typeof SECU
  sub?: string
  img?: string
  gallery?: string[]
  corp?: boolean
  market?: string
  feats?: string[]
  desc?: string
  tags?: string[]
  /** Variantes multi-modèles : [libellé, ¥, MOQ, image?] — sinon variante unique au prix usine */
  variants?: SupplierFamily['variants']
  vgroup?: string
  minOrderQty?: number
}

/** Entrée compacte : clé, nom, prix ¥, colisage [pcs/carton, kg/carton, m³/carton], options. */
function L(key: string, name: string, cny: number, pack: [number, number, number], o: LockOpts = {}): SupplierFamily {
  const [pcs, kg, m3] = pack
  return {
    key,
    name,
    category: o.cat || (o.sub === QUINC ? BRICO : o.sub === DOMOTIQUE ? DOMOTIQUE_CAT : SECU),
    subCategory: o.sub || SERRURES,
    corporate: o.corp,
    image: o.img || '',
    gallery: o.gallery,
    weightKg: Math.round((kg / pcs) * 100) / 100,
    volumeM3: Math.round((m3 / pcs) * 10000) / 10000,
    marketLike: o.market,
    minOrderQty: o.minOrderQty,
    variantGroup: o.vgroup || 'Modèle',
    variants: o.variants || [['Standard', cny, pcs, o.img]],
    description: o.desc || '',
    features: o.feats,
    tags: o.tags,
  }
}

